import numpy as np, json, itertools
import matplotlib
matplotlib.use('Agg')
import matplotlib.pyplot as plt

atoms=[]
for line in open('opt.xyz').read().splitlines()[2:]:
    p=line.split(); atoms.append((p[0],np.array([float(p[1]),float(p[2]),float(p[3])])))
cov={'H':0.31,'C':0.76,'N':0.71,'P':1.07,'Co':1.24}
bonds=[]
for i,j in itertools.combinations(range(len(atoms)),2):
    dd=np.linalg.norm(atoms[i][1]-atoms[j][1])
    if dd < cov[atoms[i][0]]+cov[atoms[j][0]]+0.25: bonds.append((i,j))
colors={'Co':'#e070a0','N':'#3050f8','P':'#ff8000','C':'#c7a23f','H':'#dddddd'}
sizes={'Co':420,'N':260,'P':320,'C':220,'H':60}
R = np.array([[1,0,0],[0,0,1],[0,-1,0]], float)  # x'=x, y'=z, z'=-y  (Co1 up)
xyz = np.array([R@a[1] for a in atoms])

fig,axs=plt.subplots(1,2,figsize=(16,8))
for ax,(c1,c2,ttl) in zip(axs,[(0,1,'front (x,y)'),(2,1,'side (z,y)')]):
    order=np.argsort(xyz[:, {0:2,2:0,1:2}[c1] if False else 2-c2])
    for i,j in bonds:
        ax.plot([xyz[i,c1],xyz[j,c1]],[xyz[i,c2],xyz[j,c2]],color='#888888',lw=1.4,zorder=1)
    for k,(el,_) in enumerate(atoms):
        ax.scatter(xyz[k,c1],xyz[k,c2],s=sizes[el],c=colors[el],edgecolors='k',linewidths=0.4,zorder=3 if el!='H' else 2)
    ax.set_aspect('equal'); ax.set_title(ttl); ax.axis('off')
plt.tight_layout(); plt.savefig('render.png',dpi=110,bbox_inches='tight')
print('saved render.png')
