import numpy as np, json, itertools
atoms=[]
for line in open('opt2.xyz').read().splitlines()[2:]:
    p=line.split(); atoms.append((p[0],np.array([float(p[1]),float(p[2]),float(p[3])])))
labels=json.load(open('labels.json'))
def v(a,b): return atoms[labels[a]][1]-atoms[labels[b]][1]
def ang(a,b,c):
    u=v(a,b)/np.linalg.norm(v(a,b)); w=v(c,b)/np.linalg.norm(v(c,b))
    return np.degrees(np.arccos(np.clip(np.dot(u,w),-1,1)))
def d(a,b): return np.linalg.norm(v(a,b))
print("Co1-Co2-N5:", round(ang('Co1','Co2','N5'),1), " Co2-N5-N6:", round(ang('Co2','N5','N6'),1))
pairs=[('Co1','Co2'),('Co1','N1'),('Co1','N2'),('Co1','N3'),('Co1','N4'),
       ('Co2','N3'),('Co2','P1'),('Co2','P2'),('Co2','P3'),('Co2','N5'),('N5','N6'),('N3','P1')]
for a,b in pairs: print(f"{a:5s}-{b:5s} {d(a,b):.3f}")
# connectivity recheck
cov={'H':0.31,'C':0.76,'N':0.71,'P':1.07,'Co':1.24}
bonds=set()
for i,j in itertools.combinations(range(len(atoms)),2):
    dd=np.linalg.norm(atoms[i][1]-atoms[j][1])
    if dd<cov[atoms[i][0]]+cov[atoms[j][0]]+0.25: bonds.add((i,j))
inv={v:k for k,v in labels.items()}
from collections import defaultdict
deg=defaultdict(list)
for i,j in bonds: deg[i].append(j); deg[j].append(i)
ok=True
exp={'Co1':5,'Co2':6,'N1':3,'N2':3,'N3':4,'N4':3,'N5':2,'N6':1,'P1':4,'P2':4,'P3':4}
for k,e in exp.items():
    got=len(deg[labels[k]])
    if got!=e: ok=False; print("MISMATCH",k,got,"expected",e)
print("connectivity OK:", ok, " total bonds:", len(bonds))
# short contacts
bad=[]
for i,j in itertools.combinations(range(len(atoms)),2):
    dd=np.linalg.norm(atoms[i][1]-atoms[j][1]); ei,ej=atoms[i][0],atoms[j][0]
    if dd<1.2 and ei!='H' and ej!='H' and (i,j)!=(labels['N5'],labels['N6']): bad.append((i,ei,j,ej,round(dd,2)))
print("short heavy pairs:", bad)
